<?php $badge = function ($s) { include APP_ROOT . '/views/partials/status.php'; }; ?>
<div class="topbar"><h1>Support</h1></div>
<?php if (!$rows): ?><div class="empty">No tickets.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Ticket</th><th>Customer</th><th>Category</th><th>Priority</th><th>Sentiment</th><th>Assigned</th><th>Status</th><th>Updated</th></tr></thead><tbody>
<?php foreach ($rows as $t): ?><tr><td><a href="/admin/tickets/<?= e($t['number']) ?>"><b><?= e($t['subject']) ?></b></a><div class="small muted"><?= e($t['number']) ?></div></td><td class="small"><?= e($t['name'] ?: $t['email'] ?: 'Visitor') ?></td><td class="small"><?= e($t['category']) ?></td><td><?php $badge($t['priority']); ?></td><td class="small"><?= e($t['sentiment']) ?></td><td class="small"><?= e($t['assigned_to']) ?></td><td><?php $badge($t['status']); ?></td><td class="small"><?= e(substr($t['updated_at'], 0, 16)) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
